{"task": "Find log messages that contain a long base64-looking token of at least 20 characters", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9+/]{20,}={0,2}')"}
{"task": "Count how many log lines per service contain base64 tokens embedded after an 'Authorization: Bearer' prefix", "sql": "SELECT service, COUNT(*) AS bearer_token_count FROM logs WHERE regexp_like(message, 'Bearer\\s+[A-Za-z0-9+/]{16,}={0,2}') GROUP BY service"}
{"task": "List ERROR level logs where the message contains a base64 token padded with = or == at the end", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '[A-Za-z0-9+/]{4,}={1,2}(?![A-Za-z0-9+/=])')"}
{"task": "Flag messages whose base64-looking substring exceeds 100 characters as potentially oversized tokens", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '[A-Za-z0-9+/]{100,}={0,2}') THEN 'oversized_token' ELSE 'normal' END AS token_size FROM logs WHERE regexp_like(message, '[A-Za-z0-9+/]{20,}={0,2}')"}
{"task": "Identify logs containing JWT-style tokens made of three dot-separated base64url segments", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9_-]{10,}\\.[A-Za-z0-9_-]{10,}\\.[A-Za-z0-9_-]{10,}')"}
{"task": "Join events and logs to correlate HTTP paths with embedded base64 tokens against log lines mentioning a token", "sql": "SELECT e.id, e.path, l.message FROM events e JOIN logs l ON regexp_like(l.message, '[A-Za-z0-9+/]{20,}={0,2}') AND regexp_like(e.path, '[A-Za-z0-9+/]{20,}={0,2}')"}
{"task": "Find request paths with a query parameter value that looks like a base64 token, such as token= or data=", "sql": "SELECT id, path, status FROM events WHERE regexp_like(path, '[?&](token|data|session)=[A-Za-z0-9+/]{16,}={0,2}')"}
{"task": "Count distinct services reporting DEBUG logs that leak what appears to be base64 encoded credentials", "sql": "SELECT COUNT(DISTINCT service) AS services_with_leaked_tokens FROM logs WHERE level = 'DEBUG' AND regexp_like(message, '(?i)(password|secret|token)[:=]\\s*[A-Za-z0-9+/]{16,}={0,2}')"}
{"task": "Sample the most recent 50 log lines containing base64url-safe tokens (using - and _ instead of + and /)", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9_-]{24,}') ORDER BY ts DESC LIMIT 50"}
{"task": "Break down counts of log messages per level that do versus do not contain a base64-like token for triage prioritization", "sql": "SELECT level, CASE WHEN regexp_like(message, '[A-Za-z0-9+/]{20,}={0,2}') THEN 'has_token' ELSE 'no_token' END AS token_status, COUNT(*) AS log_count FROM logs GROUP BY level, token_status"}

